function layoutCtrl(n,t,i){"use strict";if(JSON.parse(localStorage.getItem("userData"))===null){location.href="/Login";return}let r=JSON.parse(localStorage.getItem("userData"));n.menus=r.menus;n.subMenus=r.submenus;n.permissions=r.permissions;n.accions=r.actions;n.usuario=r.username;n.politica=r.role;n.entidad=r.tradeName;n.nombreComercial=r.bussinesName;n.drawMenus=function(){let t="";t+=`<li class="user-pro">
                <a class="has-arrow waves-effect waves-dark" href="javascript:void(0)" aria-expanded="false">
                    <img src="/assets/images/user/user.png" alt="" class="img-circle">
                    <span class="hide-menu">${r.fullname}</span>
                </a>
                <ul aria-expanded="false" class="collapse">
                    <li><a href="/Usuario/Perfil"><i class="ti-user"></i> Mi Perfil</a></li>
                    <li><a href="#" onclick="logout()" id="logoutII"><i class="fa fa-power-off"></i> Salir</a></li>
                </ul>
            </li>`;for(let i=0;i<n.menus.length;i++){t+="<\/ul><\/li>";t+=`<li>
                                <a class="has-arrow waves-effect waves-dark" href="javascript:void(0)" aria-expanded="false">
                                    <i class="${n.menus[i].icono}"></i>
                                    <span class="hide-menu"> ${n.menus[i].descripcion}</span>
                                </a>
                <ul aria-expanded="false" class="collapse">`;for(let r=0;r<n.subMenus.length;r++)n.menus[i].idMenu==n.subMenus[r].idMenu&&(t+='<li><a href="'+n.subMenus[r].url+'">'+n.subMenus[r].descripcion+"<\/a><\/li>")}$("#sidebarnav").html(t)};(n.menus.length>0||n.subMenus.length>0)&&n.drawMenus();const u=i.location.pathname;if(u&&(u==="/"&&(location.href="/Home/Index"),u.indexOf("/Home")==-1)){let i=u.split("/").splice(1).length;if([1,2].includes(i)){let r=u.indexOf("/Index")==-1?u+"/Index":u,i=n.subMenus.find(n=>n.url===r);i?(t.usuarioPermiso={almacenPermiso:JSON.parse(n.permissions.find(n=>n.codModule=="AR").permission),ventaPermiso:JSON.parse(n.permissions.find(n=>n.codModule=="V").permission),cajaPermiso:JSON.parse(n.permissions.find(n=>n.codModule=="C").permission)},n.accion=i,t.articlePermission=n.accions[0],t.ventaPermiso=t.usuarioPermiso.ventaPermiso):location.href="/Home/Index"}}n.onChangeSubMenu=function(n){try{location.href=n.url}catch(t){location.href="/Login/Logout"}};n.logout=function(){Object.keys(localStorage).forEach(function(n){localStorage.removeItem(n)});location.href="/Login"}}angular.module("acontPlusApp").controller("layoutCtrl",layoutCtrl);layoutCtrl.$inject=["$scope","$rootScope","$window","mainService",];